UPDATE USER
   SET nickname = #{nickname}
     , update_time = #{updateTime}
 WHERE user_id = #{userId}

UPDATE USER
   SET is_withdraw = 1
     , update_time = #{updateTime}
 WHERE user_id = #{userId}
   AND is_withdraw = 0

UPDATE USER
   SET password = #{password}
     , update_time = #{updateTime}
 WHERE user_id = #{userId}
   AND is_withdraw = 0
